import { useState, type ReactNode } from "react";
import { Stack } from "@/shared/ui/layout/Stack";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Chip } from "@/shared/ui/data/Chip";
import { CardListRow } from "@/shared/ui/data/CardListRow";
import { KeyValueList } from "@/shared/ui/data/KeyValueList";
import { MasterDetail } from "@/shared/ui/layouts/MasterDetail";
import { PageHeader } from "@/shared/ui/pages/PageHeader";

export type CollectionBadgeTone = "neutral" | "accent" | "success" | "info" | "danger";
export interface CollectionItem {
  id: string;
  title: ReactNode;
  subtitle?: ReactNode;
  badge?: string;
  badgeTone?: CollectionBadgeTone;
  meta?: ReactNode;
  facts?: { k: ReactNode; v: ReactNode }[];
}
export interface CollectionPageProps {
  title?: ReactNode;
  hint?: ReactNode;
  toolbar?: ReactNode;
  items?: CollectionItem[];
  selectedId?: string | null;
  defaultSelectedId?: string;
  onSelect?: (id: string) => void;
  detail?: (item: CollectionItem) => ReactNode;
  railWidth?: number;
  className?: string;
  loading?: boolean;
}
const DEMO_ITEMS: CollectionItem[] = [
  { id: "sr", title: "Senior Reviewer", subtitle: "Reviews diffs", badge: "planner", facts: [{ k: "model", v: "opus" }] },
  { id: "ab", title: "API Builder", badge: "worker", badgeTone: "success", meta: "14m" },
];
export function CollectionPage({
  title = "Personas", hint, toolbar,
  items = DEMO_ITEMS,
  selectedId, defaultSelectedId, onSelect,
  detail, railWidth = 280, className, loading = false,
}: CollectionPageProps) {
  const controlled = selectedId !== undefined;
  const [innerSelected, setInnerSelected] = useState<string | null>(defaultSelectedId ?? null);
  const selected = controlled ? selectedId : innerSelected;
  const select = (id: string) => {
    if (!controlled) setInnerSelected(id);
    onSelect?.(id);
  };
  const item = items.find((i) => i.id === selected);

  if (loading) {
    return (
      <MasterDetail
        className={className} railWidth={railWidth}
        toolbar={<PageHeader title={title} hint={hint} toolbar={toolbar} />}
        rail={<Stack gap={8}>{Array.from({ length: 6 }).map((_, i) => <Skeleton key={i} h={38} radius={6} />)}</Stack>}
        detail={<Stack gap={10}><Skeleton w="40%" h={16} /><Skeleton w="90%" h={11} /><Skeleton w="70%" h={11} /></Stack>}
      />
    );
  }

  const defaultDetail = (it: CollectionItem): ReactNode => (
    <Stack gap={12}>
      <div style={{ fontSize: 14, fontWeight: 600 }}>{it.title}</div>
      {it.subtitle != null && <div style={{ fontSize: 12, color: "var(--fg-muted)" }}>{it.subtitle}</div>}
      {it.facts && it.facts.length > 0 && <KeyValueList items={it.facts} />}
    </Stack>
  );

  return (
    <MasterDetail
      className={className}
      toolbar={<PageHeader title={title} hint={hint} toolbar={toolbar} meta={String(items.length)} />}
      railWidth={railWidth}
      rail={
        items.length > 0 ? (
          <Stack gap={6}>
            {items.map((it) => (
              <CardListRow key={it.id}
                title={it.title}
                subtitle={it.subtitle}
                badge={it.badge != null ? <Chip size="xs" tone={it.badgeTone ?? "neutral"}>{it.badge}</Chip> : undefined}
                trailing={it.meta != null ? <span style={{ fontFamily: "var(--mono)", fontSize: 10, color: "var(--fg-dim)" }}>{it.meta}</span> : undefined}
                selected={selected === it.id}
                onClick={() => select(it.id)}
              />
            ))}
          </Stack>
        ) : (
          <EmptyState title="Nothing here yet" description="Items appear here as the collection fills." />
        )
      }
      detail={
        item ? (detail ? detail(item) : defaultDetail(item)) : (
          <EmptyState title="No item selected" description="Select an item in the list to inspect it." />
        )
      }
    />
  );
}

